// Input: 44 features in the exact order listed above.
// Output probabilities are ordered [GOOD, ACCEPTABLE, POOR].
// NaN/Inf values are replaced using the fitted SimpleImputer medians.
static inline VitalSyncModel3Prediction vitalSyncModel3Predict(const float input[VITALSYNC_M3_N_FEATURES]) {
  float x[VITALSYNC_M3_N_FEATURES];
  for (int i = 0; i < VITALSYNC_M3_N_FEATURES; ++i) {
    float v = input[i];
    x[i] = isfinite(v) ? v : pgm_read_float(&VITALSYNC_M3_IMPUTE[i]);
  }

  double sums[3] = {0.0, 0.0, 0.0};
  for (uint16_t t = 0; t < VITALSYNC_M3_N_TREES; ++t) {
    uint16_t node = pgm_read_word(&VITALSYNC_M3_ROOTS[t]);
    while (true) {
      int8_t fi = (int8_t)pgm_read_byte(&VITALSYNC_M3_FEATURE[node]);
      if (fi < 0) break;
      float th = pgm_read_float(&VITALSYNC_M3_THRESHOLD[node]);
      if (x[(uint8_t)fi] <= th) node = pgm_read_word(&VITALSYNC_M3_LEFT[node]);
      else                      node = pgm_read_word(&VITALSYNC_M3_RIGHT[node]);
    }
    uint32_t base = (uint32_t)node * 3U;
    for (uint8_t c = 0; c < 3; ++c) {
      sums[c] += (double)pgm_read_word(&VITALSYNC_M3_LEAF_PROB_Q16[base + c]) / 65535.0;
    }
  }

  VitalSyncModel3Prediction out;
  float invTrees = 1.0f / (float)VITALSYNC_M3_N_TREES;
  uint8_t best = 0;
  for (uint8_t c = 0; c < 3; ++c) {
    out.probabilities[c] = (float)(sums[c] * invTrees);
    if (out.probabilities[c] > out.probabilities[best]) best = c;
  }
  out.predictedClass = best;
  return out;
}

static inline const char* vitalSyncModel3ClassName(uint8_t c) {
  switch (c) {
    case VITALSYNC_M3_GOOD: return "GOOD";
    case VITALSYNC_M3_ACCEPTABLE: return "ACCEPTABLE";
    case VITALSYNC_M3_POOR: return "POOR";
    default: return "UNKNOWN";
  }
}
